#!/usr/bin/env python3
"""Record the visible alpha bounds of the bundled library thumbnails."""

import argparse
from pathlib import Path

from PIL import Image

ROOT = Path(__file__).resolve().parents[2]
THUMBNAILS = ROOT / "assets/public_posters/r2-v11/thumbnail"
OUTPUT = ROOT / "lib/hip/data/hip_library_poster_bounds.dart"
THUMBNAIL_SIZE = 192


def generate() -> str:
    posters = sorted(THUMBNAILS.glob("*.webp"))
    if not posters:
        raise ValueError(f"No thumbnails in {THUMBNAILS}")

    lines = [
        "// Generated by tools/media/build_library_poster_bounds.py.",
        "import 'dart:ui' show Rect;",
        "",
        f"const libraryPosterPixels = {THUMBNAIL_SIZE}.0;",
        "const libraryPosterBounds = <String, Rect>{",
    ]
    for path in posters:
        with Image.open(path) as image:
            if image.size != (THUMBNAIL_SIZE, THUMBNAIL_SIZE) or image.mode != "RGBA":
                raise ValueError(f"Unexpected thumbnail format: {path.name}")
            bounds = image.getchannel("A").getbbox()
        if bounds is None:
            raise ValueError(f"Thumbnail is fully transparent: {path.name}")
        coordinates = ", ".join(str(value) for value in bounds)
        lines.append(f"  '{path.stem}': Rect.fromLTRB({coordinates}),")
    return "\n".join([*lines, "};", ""])


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="Check the generated file")
    args = parser.parse_args()
    content = generate()
    if args.check:
        if OUTPUT.read_text(encoding="utf-8") != content:
            raise SystemExit(f"Regenerate {OUTPUT.relative_to(ROOT)}")
    else:
        OUTPUT.write_text(content, encoding="utf-8", newline="\n")


if __name__ == "__main__":
    main()
